use std::{fs,path::{Path,PathBuf},thread,time::{Duration,Instant},sync::atomic::Ordering};
use lito_modern::modern_lito::{native_mode_menu::{Menu,Hit,Filter},native_multisector_resources::{self,Inputs},native_city_runtime::{Runtime,Action,UiPage},native_resources::BytePin};
use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn hit(v:&Value)->Option<Hit>{match v.as_str(){Some("Up")=>Some(Hit::Up),Some("Down")=>Some(Hit::Down),Some("Thumb")=>Some(Hit::Thumb),None=>None,Some(s)=>panic!("unknown event hit {s}")}}
fn input(p:&Path,name:&str)->Inputs{let manifest=p.join(format!("logs/continuation-20261003/{name}"));let b=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:b.len()as u64,sha256:Sha256::digest(b).into()}}}
fn wait(mut f:impl FnMut()->bool){let end=Instant::now()+Duration::from_secs(60);while !f(){assert!(Instant::now()<end,"R487 bounded new event wait");thread::sleep(Duration::from_millis(5));}}
fn snap(m:&Menu,changed:bool)->Value{json!({"top":m.top,"selected":m.selected,"pressed":m.pressed.map(|h|format!("{h:?}")),"repeat_due":m.repeat_deadline(),"changed":changed})}
fn main()->anyhow::Result<()>{
 let p=PathBuf::from(std::env::args_os().nth(1).expect("project"));let begin=Instant::now();let i=input(&p,"r486-map-binding.json");let(_,plans,rows)=native_multisector_resources::load(&i)?;assert_eq!((plans.len(),rows.len()),(40,40));
 let spec:Value=serde_json::from_slice(&fs::read(p.join("logs/continuation-20261003/r487-event-input.json"))?)?;let mut traces=Vec::new();let mut total=0;
 for case in spec["cases"].as_array().unwrap(){let mut m=Menu::for_filter(&rows,Filter::DiagnosticAll)?;assert_eq!(m.count(),case["count"].as_u64().unwrap()as usize);m.top=case["initial_top"].as_u64().unwrap()as usize;let mut actual=Vec::new();
  for e in case["events"].as_array().unwrap(){let t=e["time_ms"].as_u64().unwrap();let h=hit(&e["hit"]);let changed=match e["kind"].as_str().unwrap(){"down"=>{assert_eq!(m.down_at(h,t),None);false},"move"=>{m.pointer_move_at(h,t);false},"tick"=>m.repeat_at(t),"release"=>m.release(h),"cancel"=>{m.cancel_press();false},kind=>panic!("unknown event {kind}")};let state=snap(&m,changed);assert_eq!(state,e["expected"],"case {} event {}",case["name"],e);actual.push(json!({"input":e,"actual":state,"matches_expected":true}));total+=1;}
  traces.push(json!({"name":case["name"],"actual_events":actual}));
 }
 assert_eq!(total,spec["events"].as_u64().unwrap());
 // Native-scaled hit and movement route: same target retains deadline; outside
 // cancels it, returning re-arms from that move's time. No GUI/input is used.
 let mut dpi_checks=0;for(w,h)in[(157,81),(628,324),(1256,648)]{let l=lito_modern::modern_lito::native_offline_menu_skin::Layout::fit(24,156,w,h).unwrap();let mut m=Menu::for_filter(&rows,Filter::DiagnosticAll)?;let(x,y)=l.point(146,70);let target=m.hit(&l,x,y);assert_eq!(target,Some(Hit::Down));m.down_at(target,100);m.pointer_move_at(m.hit(&l,x,y),500);assert_eq!(m.repeat_deadline(),Some(800));let outside=m.hit(&l,l.x-1,l.y);assert_eq!(outside,None);m.pointer_move_at(outside,700);assert!(!m.repeat_at(1000));m.pointer_move_at(target,1000);assert_eq!(m.repeat_deadline(),Some(1700));assert!(m.repeat_at(1700));assert!(m.release(target));assert_eq!(m.top,2);dpi_checks+=1;}
 // Only new lifecycle cancellation through the actual current worker. No old
 // map preview batch is executed; active load is cancelled before publishing.
 let mut rt=Runtime::start(i)?;wait(||{rt.poll();rt.page()==UiPage::Menu});let mut life=Vec::new();
 rt.menu_mut().unwrap().down_at(Some(Hit::Down),100);assert_eq!(rt.menu().unwrap().repeat_deadline(),Some(800));let before=snap(rt.menu().unwrap(),false);rt.handle(Action::Filter(Filter::Mode{mode:3,alternate:false}))?;assert_eq!(rt.menu().unwrap().repeat_deadline(),None);assert_eq!(rt.menu().unwrap().pressed,None);assert_eq!(rt.menu().unwrap().top,0);life.push(json!({"input":"different-mode filter while held","before":before,"after":snap(rt.menu().unwrap(),false),"no_late_repeat":!rt.menu_mut().unwrap().repeat_at(1000)}));
 rt.handle(Action::Select(3,563))?;rt.menu_mut().unwrap().down_at(Some(Hit::Down),2000);assert_eq!(rt.menu().unwrap().repeat_deadline(),Some(2700));rt.handle(Action::Enter)?;wait(||rt.progress().load_active.load(Ordering::Acquire));let before=snap(rt.menu().unwrap(),false);rt.handle(Action::Back)?;assert_eq!(rt.page(),UiPage::Menu);assert_eq!(rt.menu().unwrap().pressed,None);assert_eq!(rt.menu().unwrap().repeat_deadline(),None);assert!(!rt.menu_mut().unwrap().repeat_at(5000));wait(||!rt.progress().load_active.load(Ordering::Acquire));rt.poll();assert!(rt.frame().is_none());life.push(json!({"input":"Back during actual active563load with held arrow","before":before,"after":snap(rt.menu().unwrap(),false),"selected_identity":[rt.choice().unwrap().mode,rt.choice().unwrap().map_id],"no_frame":true,"no_late_repeat":true}));
 rt.menu_mut().unwrap().down_at(Some(Hit::Down),6000);let before=snap(rt.menu().unwrap(),false);rt.handle(Action::Close)?;assert_eq!(rt.menu().unwrap().repeat_deadline(),None);assert_eq!(rt.menu().unwrap().pressed,None);wait(||{rt.poll();rt.page()==UiPage::Closed});assert!(rt.progress().retired.load(Ordering::Acquire));life.push(json!({"input":"close while held","before":before,"after":snap(rt.menu().unwrap(),false),"actual_worker_retired":true}));
 let d=json!({"state":"R487_SOURCE_DERIVED_ARROW_HOLD_FINITE_EVENT_SEQUENCE_AND_ACTUAL_LIFECYCLE_PASS_GUI_PENDING","cases":traces.len(),"events":total,"traces":traces,"scaled_pointer_sequences":dpi_checks,"lifecycle":life,"actual_active_Back_cancel":true,"actual_worker_retired":true,"no_preview_frame_published":true,"historical_PASS_batches_rerun":0,"focused_seconds":begin.elapsed().as_secs_f64(),"thumb_display_only":true,"track_not_implemented_geometry_lifecycle_unresolved":true,"flag_writer_proven_but_default_ordinary_policy_unchanged":true,"complete_modes":16,"total_modes":40,"static_CPU_previews":40,"GUI":0,"LOADED":false});fs::write(p.join("logs/continuation-20261003/r487-event-details.json"),serde_json::to_vec_pretty(&d)?)?;println!("R487 focused PASS:{}cases/{total}fixed events/{dpi_checks}scaled sequences/3actual lifecycle;noGUI;{:.3}s",traces.len(),begin.elapsed().as_secs_f64());Ok(())
}
